type Page='home'|'receitas'|'despesas'|'cartoes'|'categorias'|'compromissos'|'jardim'|'planos'|'conta'|'suporte'|'feedback'|'admin';
const ISO_CURRENCY_CODES:string[]=(()=>{try{return [...(((Intl as any).supportedValuesOf?.('currency'))||[])].sort()}catch{return ['BRL','EUR','JPY','USD']}})();
const IANA_TIME_ZONES:string[]=(()=>{try{return [...(((Intl as any).supportedValuesOf?.('timeZone'))||[])].sort()}catch{return ['America/Sao_Paulo','Asia/Tokyo','UTC']}})();
const PIE_COLORS=['#225c3b','#4f8a62','#7eaa89','#b1cdb7','#d5e4d7','#6b806f','#a5b5a8'];
function money(value:number,currency:string){return new Intl.NumberFormat('pt-BR',{style:'currency',currency,maximumFractionDigits:currency==='JPY'?0:2}).format(value)}
function localDate(v:string){return new Date(v).toLocaleDateString('pt-BR')}
function localDateTime(v:string){return new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
function activityEntityLabel(e:FamilyActivityEvent){
  const p=e.metadata||{},before=p.before||{},actor=e.actor_name||'Folhinha';
  const action=e.action==='created'?'registrou':e.action==='updated'?'alterou':'excluiu';
  if(e.entity_type==='transactions'){
    const label=p.description||before.description||'movimentação',cur=p.currency||before.currency||'BRL',amount=Number(p.amount??before.amount??0);
    if(e.action==='updated'&&before.amount!=null&&p.amount!=null&&Number(before.amount)!==Number(p.amount))return actor+' alterou “'+label+'” de '+money(Number(before.amount),String(before.currency||cur))+' para '+money(Number(p.amount),String(cur));
    return actor+' '+action+' '+(p.kind==='receita'||before.kind==='receita'?'a receita ':'o gasto ')+'“'+label+'”'+(amount>0?' • '+money(amount,String(cur)):'');
  }
  if(e.entity_type==='credit_card_purchases')return actor+' '+action+' uma compra no cartão: “'+String(p.description||before.description||'compra')+'”'+(p.amount!=null?' • '+money(Number(p.amount),String(p.currency||'BRL')):'');
  if(e.entity_type==='recurring_expenses')return actor+' '+action+' a recorrência “'+String(p.description||before.description||'conta recorrente')+'”';
  if(e.entity_type==='commitments')return actor+' '+action+' o compromisso “'+String(p.title||before.title||'compromisso')+'”';
  if(e.entity_type==='deadline_tasks')return actor+' '+action+' a tarefa “'+String(p.title||before.title||'tarefa')+'”';
  if(e.entity_type==='savings_goals')return actor+' '+action+' uma meta de economia'+(p.amount!=null?' • '+money(Number(p.amount),String(p.currency||'BRL')):'');
  if(e.entity_type==='credit_cards')return actor+' '+action+' o cartão “'+String(p.name||before.name||'cartão')+'”';
  if(e.entity_type==='category_budgets')return actor+' '+action+' o orçamento de '+String(p.category||before.category||'categoria')+(p.monthly_limit!=null?' • '+money(Number(p.monthly_limit),String(p.currency||'BRL')):'');
  return actor+' '+action+' uma informação da família';
}
function activityIcon(e:FamilyActivityEvent){if(e.entity_type==='transactions')return e.metadata?.kind==='receita'?'💰':'💸';if(e.entity_type==='credit_card_purchases'||e.entity_type==='credit_cards')return'💳';if(e.entity_type==='recurring_expenses')return'🔁';if(e.entity_type==='commitments'||e.entity_type==='deadline_tasks')return'📆';if(e.entity_type==='savings_goals'||e.entity_type==='category_budgets')return'🎯';return'🍃'}
function dateInput(v:string){const d=new Date(v);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}

function csvCell(value:string|number){const s=String(value??'');return `"${s.replace(/"/g,'""')}"`}
function exportTransactionsCsv(items:Tx[],kind:'receita'|'gasto'){
  const rows=[['Data','Descrição','Categoria','Moeda','Valor','Origem'],...items.map(t=>[localDate(t.occurred_at),t.description,t.category,t.currency,t.amount,t.source||''])];
  const csv='\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');
  a.href=url;a.download=`planeja-mais-${kind==='receita'?'receitas':'despesas'}-${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
}

function downloadPortableFile(filename:string,content:string,type:string){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function familyTransactionsCsv(bundle:any){
  const shared=bundle?.shared_data||bundle?.data||{},names=bundle?.household?.member_names||{};
  const cards=new Map<number,string>((shared.credit_cards||[]).map((x:any)=>[Number(x.id),String(x.name||'Cartão')]));
  const rows:Array<Array<string|number>>=[['Tipo de registro','Data','Membro','Descrição','Categoria','Moeda','Valor','Valor total original','Cartão','Parcela','Origem']];
  for(const t of shared.transactions||[])rows.push([
    t.kind==='receita'?'Receita':'Gasto',t.occurred_at||t.created_at||'',names[String(t.user_id)]||'Membro',
    t.description||'',t.category||'',t.currency||'',Number(t.amount||0),'','','',t.source||''
  ]);
  for(const p of shared.credit_card_purchases||[])rows.push([
    'Compra no cartão',p.purchased_at||p.created_at||'',names[String(p.user_id)]||'Membro',
    p.description||'',p.category||'',p.currency||'',Number(p.amount||0),Number(p.original_total??p.amount??0),
    cards.get(Number(p.credit_card_id))||'Cartão',Number(p.installment_count||1)>1?String(p.installment_number||1)+'/'+String(p.installment_count||1):'1/1',p.source||''
  ]);
  rows.splice(1,rows.length-1,...rows.slice(1).sort((a,b)=>String(b[1]).localeCompare(String(a[1]))));
  return '\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n');
}

function signupPhone(value:string){const digits=value.replace(/\D/g,'');if(digits.length<8||digits.length>15)throw new Error('Informe o telefone com código do país, por exemplo +81 90 1234 5678.');return `+${digits}`}
function Auth(){
  const params=new URLSearchParams(window.location.search);const inviteFromUrl=(params.get('invite')||'').trim();
  const storedInvite=localStorage.getItem('planeja_beta_invite')||'';const invite=inviteFromUrl||storedInvite;
  const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[firstName,setFirstName]=useState('');const[phone,setPhone]=useState('');
  const[preferredChat,setPreferredChat]=useState<'whatsapp'|'telegram'>('whatsapp');const[consent,setConsent]=useState(false);
  const[mode,setMode]=useState<'login'|'signup'|'forgot'>(invite?'signup':'login');const[msg,setMsg]=useState('');const[busy,setBusy]=useState(false);const[captchaToken,setCaptchaToken]=useState<string|null>(null);const[captchaEpoch,setCaptchaEpoch]=useState(0);
  useEffect(()=>{if(inviteFromUrl){localStorage.setItem('planeja_beta_invite',inviteFromUrl);const url=new URL(window.location.href);url.searchParams.delete('invite');window.history.replaceState({},'',url.pathname+(url.searchParams.size?'?'+url.searchParams.toString():'')+url.hash)}},[inviteFromUrl]);
  async function submit(e:FormEvent){
    e.preventDefault();setBusy(true);setMsg('');
    try{
      if(mode==='forgot'){if(turnstileEnabled&&!captchaToken)throw new Error('Aguarde um instante enquanto protegemos seu acesso.');const{error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin,captchaToken:captchaToken||undefined});setMsg(error?error.message:'Se esse e-mail estiver cadastrado, você receberá um link para criar uma nova senha. 🍃');return;}
      if(mode==='login'){if(turnstileEnabled&&!captchaToken)throw new Error('Aguarde um instante enquanto protegemos seu acesso.');const result=await supabase.auth.signInWithPassword({email,password,options:captchaToken?{captchaToken}:undefined});if(result.error)throw result.error;return;}
      if(!invite)throw new Error('O beta está fechado. O cadastro só é liberado por um link de convite.');
      if(!firstName.trim())throw new Error('Informe seu nome.');if(preferredChat==='whatsapp'&&!consent)throw new Error('Confirme que você quer receber a primeira mensagem da Folhinha no seu WhatsApp.');
      await assertSafeNewPassword(password);if(turnstileEnabled&&!captchaToken)throw new Error('Aguarde um instante enquanto protegemos seu acesso.');const cleanPhone=signupPhone(phone);const valid=await validateBetaInvite(invite,email);if(!valid)throw new Error('Este convite é inválido, expirou ou foi emitido para outro e-mail.');
      const redirect=`${window.location.origin}/?invite=${encodeURIComponent(invite)}`;
      const result=await supabase.auth.signUp({email,password,options:{emailRedirectTo:redirect,captchaToken:captchaToken||undefined,data:{first_name:firstName.trim(),phone_e164:cleanPhone,preferred_chat:preferredChat,chat_consent:String(consent)}}});
      if(result.error)throw result.error;
      if(result.data.session){
        await redeemBetaInvite(invite);await saveRegistrationProfile(firstName,cleanPhone,preferredChat,true);localStorage.removeItem('planeja_beta_invite');
        try{await startPaymentMethodSetup()}catch{setMsg('Cadastro criado e convite ativado. Entre na etapa seguinte para salvar seu cartão com segurança. Nenhuma cobrança será feita durante o beta. 🍃')}
      }else setMsg('Conta criada. Confirme seu e-mail para continuar. Depois da confirmação, você salvará o cartão e conectará a Folhinha. 🍃');
    }catch(err){setMsg(err instanceof Error?err.message:'Não foi possível concluir o cadastro.')}finally{setBusy(false);if(turnstileEnabled){setCaptchaToken(null);setCaptchaEpoch(v=>v+1)}}
  }
  const signup=mode==='signup';const securityReady=!turnstileEnabled||Boolean(captchaToken);
  return <main className="auth-shell landing-auth"><section className="brand-panel"><div className="brand-lockup"><img src="/brand/planeja-logo.png" alt="Folhinha"/><div><strong>Planeja+</strong><small>Plante hoje, colha amanhã</small></div></div><p className="eyebrow">PLANEJA+ • FOLHINHA</p><h1>Organize sua vida financeira conversando.</h1><p>Você registra gastos, receitas, contas recorrentes, metas e compromissos em linguagem natural. A Folhinha organiza tudo e o painel mostra o que realmente está acontecendo com seu dinheiro.</p><div className="landing-points"><span>✓ Beta fechado por convite</span><span>✓ Cartão salvo com Stripe, sem cobrança no beta</span><span>✓ Folhinha pelo WhatsApp ou Telegram</span></div></section><section className="auth-card landing-card"><p className="eyebrow">{mode==='login'?'ACESSO':signup?'SEU CONVITE ESTÁ LIBERADO':'RECUPERAR SENHA'}</p><h2>{mode==='login'?'Entre no Planeja+':signup?'Crie sua conta beta':'Vamos criar uma senha nova'}</h2>{signup&&<p className="invite-note">O cadastro leva poucos minutos. Primeiro seus dados, depois o cartão seguro no Stripe e, por fim, a conexão com a Folhinha.</p>}<form onSubmit={submit}>{signup&&<><label>Nome<input value={firstName} onChange={e=>setFirstName(e.target.value)} autoComplete="name" required/></label><label>Seu WhatsApp<input value={phone} onChange={e=>setPhone(e.target.value)} inputMode="tel" autoComplete="tel" placeholder="+55 11 99999-9999" required/><small className="password-hint">Use o mesmo número que vai conversar com a Folhinha. Inclua o código do país.</small></label><label>Canal da Folhinha<select value={preferredChat} onChange={e=>{const v=e.target.value as 'whatsapp'|'telegram';setPreferredChat(v);if(v!=='whatsapp')setConsent(false)}}><option value="whatsapp">WhatsApp — recomendado</option><option value="telegram">Telegram</option></select></label>{preferredChat==='whatsapp'&&<label className="consent-check"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)} required/><span>Quero receber mensagens do <b>Planeja+</b> neste WhatsApp, incluindo a primeira mensagem da Folhinha e lembretes ligados às funções que eu usar. Posso desativar os lembretes depois.</span></label>}</>}<label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label>{mode!=='forgot'&&<label>Senha<input type="password" minLength={signup?PASSWORD_MIN_LENGTH:undefined} value={password} onChange={e=>setPassword(e.target.value)} autoComplete={signup?'new-password':'current-password'} required/>{signup&&<small className="password-hint">{PASSWORD_POLICY_MESSAGE} Senhas presentes em vazamentos conhecidos são recusadas.</small>}</label>}<TurnstileGate key={`${mode}-${captchaEpoch}`} action={`auth_${mode}`} onToken={setCaptchaToken}/><button disabled={busy||!securityReady}>{busy?'Aguarde…':!securityReady?'Protegendo acesso…':mode==='login'?'Entrar':signup?'Continuar cadastro':'Enviar link de recuperação'}</button></form>{msg&&<p className="form-message">{msg}</p>}{mode==='login'&&<button className="link" onClick={()=>{setMode('forgot');setMsg('')}}>Esqueci minha senha</button>}{invite&&<button className="link" onClick={()=>{setMode(mode==='signup'?'login':'signup');setMsg('')}}>{signup?'Já tenho conta':'Usar meu convite beta'}</button>}{!invite&&mode==='login'&&<p className="beta-closed">O beta é fechado. Novas contas entram somente por convite.</p>}{mode==='forgot'&&<button className="link" onClick={()=>{setMode('login');setMsg('')}}>Voltar para o login</button>}<p className="legal-mini">Ao criar a conta, você aceita os <a href="/terms.html">Termos</a> e a <a href="/privacy.html">Política de Privacidade</a>.</p></section></main>}

function ResetPassword({onDone}:{onDone:()=>void}){const[password,setPassword]=useState('');const[confirm,setConfirm]=useState('');const[msg,setMsg]=useState('');const[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();if(password!==confirm){setMsg('As senhas não conferem.');return}setBusy(true);setMsg('');try{await assertSafeNewPassword(password);const{error}=await supabase.auth.updateUser({password});if(error)throw error;await supabase.auth.signOut();setMsg('Senha alterada com sucesso. Você já pode entrar com a nova senha. 🍃');setTimeout(onDone,1200)}catch(err){setMsg(err instanceof Error?err.message:'Não foi possível alterar a senha.')}finally{setBusy(false)}}return <main className="auth-shell"><section className="brand-panel"><div className="brand-lockup compact"><img src="/brand/planeja-logo.png" alt="Folhinha"/><div><strong>Planeja+</strong><small>Plante hoje, colha amanhã</small></div></div><p className="eyebrow">PLANEJA+</p><h1>Quase lá.<br/>Escolha sua nova senha.</h1></section><section className="auth-card"><p className="eyebrow">NOVA SENHA</p><h2>Proteja sua conta</h2><form onSubmit={submit}><label>Nova senha<input type="password" minLength={PASSWORD_MIN_LENGTH} value={password} onChange={e=>setPassword(e.target.value)} required/><small className="password-hint">{PASSWORD_POLICY_MESSAGE} Senhas presentes em vazamentos conhecidos são recusadas.</small></label><label>Confirmar senha<input type="password" minLength={PASSWORD_MIN_LENGTH} value={confirm} onChange={e=>setConfirm(e.target.value)} required/></label><button disabled={busy}>{busy?'Verificando…':'Salvar nova senha'}</button></form>{msg&&<p className="form-message">{msg}</p>}</section></main>}

function TransactionEditor({tx,onClose,onSaved}:{tx:Tx,onClose:()=>void,onSaved:()=>void}){
  const[kind,setKind]=useState(tx.kind);const[amount,setAmount]=useState(String(tx.amount));const[currency,setCurrency]=useState(tx.currency);const[category,setCategory]=useState(tx.category);const[description,setDescription]=useState(tx.description);const[date,setDate]=useState(dateInput(tx.occurred_at));const[busy,setBusy]=useState(false);const[error,setError]=useState('');
  async function save(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{await updateTransaction(tx.id,{kind,amount:Number(amount),currency,category,description,occurred_at:new Date(`${date}T12:00:00`).toISOString()});onSaved();onClose()}catch(e){setError(e instanceof Error?e.message:'Erro ao salvar')}finally{setBusy(false)}}
  async function remove(){if(!confirm('Excluir esta movimentação? Essa ação não pode ser desfeita.'))return;setBusy(true);try{await deleteTransaction(tx.id);onSaved();onClose()}catch(e){setError(e instanceof Error?e.message:'Erro ao excluir')}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={onClose}><section className="modal" onMouseDown={e=>e.stopPropagation()}><div className="panel-head"><div><p className="eyebrow">EDITAR MOVIMENTAÇÃO</p><h2>{tx.description}</h2></div><button className="icon-btn" onClick={onClose}>×</button></div><form className="edit-form" onSubmit={save}><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value)}><option value="receita">Receita</option><option value="gasto">Despesa</option></select></label><label>Valor<input type="number" step="0.01" min="0.01" value={amount} onChange={e=>setAmount(e.target.value)} required/></label><label>Moeda<select value={currency} onChange={e=>setCurrency(e.target.value)}>{ISO_CURRENCY_CODES.map(c=><option key={c}>{c}</option>)}</select></label><label>Data<input type="date" value={date} onChange={e=>setDate(e.target.value)} required/></label><label>Categoria<input value={category} onChange={e=>setCategory(e.target.value)} required/></label><label className="wide">Descrição<input value={description} onChange={e=>setDescription(e.target.value)} required/></label>{error&&<p className="error wide">{error}</p>}<div className="modal-actions wide"><button type="button" className="danger" onClick={remove}>Excluir</button><button disabled={busy}>{busy?'Salvando…':'Salvar alterações'}</button></div></form></section></div>}

const SIDE_NAV:Array<{id:Page;label:string;icon:string}>=[{id:'home',label:'Home',icon:'home'},{id:'planos',label:'Planos',icon:'card'},{id:'conta',label:'Conta e configurações',icon:'settings'},{id:'feedback',label:'Ajuda e feedback',icon:'message'},{id:'suporte',label:'Suporte',icon:'help'}];
const SideIcon=({name}:{name:string})=>{const common={width:19,height:19,viewBox:'0 0 24 24',fill:'none',stroke:'currentColor',strokeWidth:1.8,strokeLinecap:'round' as const,strokeLinejoin:'round' as const};if(name==='home')return <svg {...common}><path d="M3 10.8 12 3l9 7.8"/><path d="M5.5 9.5V21h13V9.5"/><path d="M9.5 21v-6h5v6"/></svg>;if(name==='card')return <svg {...common}><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h4"/></svg>;if(name==='settings')return <svg {...common}><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1 .6 1.7 1.7 0 0 0-.4 1V21H9.6v-.09a1.7 1.7 0 0 0-1.1-1.55 1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.1 15a1.7 1.7 0 0 0-.6-1 1.7 1.7 0 0 0-1-.4H2.4V9.6h.09a1.7 1.7 0 0 0 1.55-1.1 1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.83-2.83.06.06A1.7 1.7 0 0 0 8.4 4.1a1.7 1.7 0 0 0 1-.6 1.7 1.7 0 0 0 .4-1V2.4h4v.09a1.7 1.7 0 0 0 1.1 1.55 1.7 1.7 0 0 0 1.88-.34l.06-.06 2.83 2.83-.06.06A1.7 1.7 0 0 0 19.9 8.4c.14.38.35.72.6 1 .28.25.63.39 1 .4h.1v4h-.09a1.7 1.7 0 0 0-1.55 1.1Z"/></svg>;if(name==='message')return <svg {...common}><path d="M21 11.5a8.3 8.3 0 0 1-9 8.2 9 9 0 0 1-3.8-.9L3 20l1.3-4.2A8.3 8.3 0 1 1 21 11.5Z"/><path d="M8 12h.01M12 12h.01M16 12h.01"/></svg>;return <svg {...common}><circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.4 2.4 0 1 1 3.2 2.3c-.7.3-1 .8-1 1.7v.2M12 17h.01"/></svg>};
function Sidebar({page,setPage,open,setOpen,account}:{page:Page,setPage:(p:Page)=>void,open:boolean,setOpen:(v:boolean)=>void,account:AccountInfo|null}){
  return <><div className={`drawer-scrim ${open?'show':''}`} onClick={()=>setOpen(false)}/><aside className={`sidebar utility-sidebar ${open?'open':''}`}><div className="side-brand"><img className="side-logo" src="/brand/planeja-logo.png" alt=""/><div><b>Planeja+</b><small>Menu da conta</small></div><button className="side-close" onClick={()=>setOpen(false)}>×</button></div><nav aria-label="Conta e suporte">{SIDE_NAV.map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>{setPage(n.id);setOpen(false)}}><span><SideIcon name={n.icon}/></span>{n.label}</button>)}</nav><div className="side-plan"><small>SEU PLANO</small><b>{account?.subscription_plan||'beta'}</b><span>{accountHasAccess(account)?'Acesso liberado':'Acesso suspenso'}</span></div><button className="side-logout" onClick={()=>supabase.auth.signOut()}>Sair da conta</button></aside></>
}
function MainTopNav({page,setPage,onMenu}:{page:Page,setPage:(p:Page)=>void,onMenu:()=>void}){const[launchOpen,setLaunchOpen]=useState(false);return <div className="main-topnav"><button className="utility-menu-btn" onClick={onMenu} aria-label="Abrir menu">☰</button><button className="top-logo" onClick={()=>setPage('home')} aria-label="Ir para o início"><img src="/brand/folhinha.png" alt=""/><span className="top-logo-copy"><strong>Planeja+</strong><small>Plante hoje, colha amanhã</small></span></button><nav><button className={page==='home'?'active':''} onClick={()=>setPage('home')}>Home</button><div className="launch-wrap"><button className={page==='receitas'||page==='despesas'||page==='cartoes'?'active':''} onClick={()=>setLaunchOpen(v=>!v)}>Lançamentos <small>⌄</small></button>{launchOpen&&<div className="launch-menu"><button onClick={()=>{setPage('receitas');setLaunchOpen(false)}}>Receitas</button><button onClick={()=>{setPage('despesas');setLaunchOpen(false)}}>Despesas</button><button onClick={()=>{setPage('cartoes');setLaunchOpen(false)}}>Cartões de crédito</button></div>}</div><button className={page==='compromissos'?'active':''} onClick={()=>setPage('compromissos')}>Agenda</button><button className={page==='jardim'?'active':''} onClick={()=>setPage('jardim')}>Jardim <span className="garden-nav-leaf">🌱</span></button></nav></div>}


function TransactionsPage({kind,txs,currency,onEdit}:{kind:'receita'|'gasto',txs:Tx[],currency:string,onEdit:(t:Tx)=>void}){
  const[query,setQuery]=useState('');const[category,setCategory]=useState('todas');const[period,setPeriod]=useState<'7d'|'30d'|'month'|'custom'|'all'>('7d');const[from,setFrom]=useState('');const[to,setTo]=useState('');const[page,setTxPage]=useState(1);const pageSize=20;
  const[expenseCards,setExpenseCards]=useState<CreditCard[]>([]);useEffect(()=>{if(kind==='gasto')listCreditCards().then(setExpenseCards).catch(()=>{})},[kind]);const cardPurchases=expenseCards.flatMap(c=>c.purchases.map(p=>({...p,card_name:c.name}))).filter(p=>p.currency===currency).sort((a,b)=>new Date(b.purchased_at).getTime()-new Date(a.purchased_at).getTime());
  const base=txs.filter(t=>t.kind===kind);const categories=Array.from(new Set(base.map(t=>t.category))).sort((a,b)=>a.localeCompare(b,'pt-BR'));
  const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());let startDate:Date|null=null,endDate:Date|null=null;if(period==='7d'){startDate=new Date(today);startDate.setDate(startDate.getDate()-6)}else if(period==='30d'){startDate=new Date(today);startDate.setDate(startDate.getDate()-29)}else if(period==='month'){startDate=new Date(today.getFullYear(),today.getMonth(),1)}else if(period==='custom'){startDate=from?new Date(from+'T00:00:00'):null;endDate=to?new Date(to+'T23:59:59.999'):null}
  const q=query.trim().toLocaleLowerCase('pt-BR');const list=base.filter(t=>{const d=new Date(t.occurred_at);return(!startDate||d>=startDate)&&(!endDate||d<=endDate)&&(category==='todas'||t.category===category)&&(!q||t.description.toLocaleLowerCase('pt-BR').includes(q)||t.category.toLocaleLowerCase('pt-BR').includes(q))});
  const total=list.filter(t=>t.currency===currency).reduce((s,t)=>s+t.amount,0);const pages=Math.max(1,Math.ceil(list.length/pageSize));const current=Math.min(page,pages);const visible=list.slice((current-1)*pageSize,current*pageSize);const changePeriod=(v:any)=>{setPeriod(v);setTxPage(1)};
  return <><div className="page-title"><div><p className="eyebrow">{kind==='receita'?'RECEITAS':'DESPESAS'}</p><h1>{kind==='receita'?'Receitas':'Despesas'}</h1><p>{list.length} movimentações no período</p></div><div className="page-title-actions"><button className="export-btn" disabled={!list.length} onClick={()=>exportTransactionsCsv(list,kind)}>Exportar CSV</button><div className={`page-total ${kind}`}><small>Total em {currency}</small><b>{money(total,currency)}</b></div></div></div><section className="panel transactions"><div className="transaction-filters"><select aria-label="Período" value={period} onChange={e=>changePeriod(e.target.value)}><option value="7d">Últimos 7 dias</option><option value="30d">Últimos 30 dias</option><option value="month">Este mês</option><option value="custom">Personalizado</option><option value="all">Todo o histórico</option></select>{period==='custom'&&<><input aria-label="Data inicial" type="date" value={from} onChange={e=>{setFrom(e.target.value);setTxPage(1)}}/><input aria-label="Data final" type="date" value={to} onChange={e=>{setTo(e.target.value);setTxPage(1)}}/></>}<input aria-label="Buscar movimentações" placeholder="Buscar por descrição ou categoria" value={query} onChange={e=>{setQuery(e.target.value);setTxPage(1)}}/><select aria-label="Filtrar por categoria" value={category} onChange={e=>{setCategory(e.target.value);setTxPage(1)}}><option value="todas">Todas as categorias</option>{categories.map(c=><option key={c} value={c}>{c}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Moeda</th><th>Valor</th><th></th></tr></thead><tbody>{visible.map(tx=><tr key={tx.id}><td>{localDate(tx.occurred_at)}</td><td><strong>{tx.description}</strong></td><td>{tx.category}</td><td>{tx.currency}</td><td>{money(tx.amount,tx.currency)}</td><td><button className="mini" onClick={()=>onEdit(tx)}>Alterar</button></td></tr>)}</tbody></table></div>{!list.length&&<p className="empty">Nenhuma movimentação neste período.</p>}{list.length>0&&<div className="tx-pagination"><span>{(current-1)*pageSize+1}–{Math.min(current*pageSize,list.length)} de {list.length}</span><div><button className="mini" disabled={current<=1} onClick={()=>setTxPage(p=>Math.max(1,p-1))}>← Anterior</button><b>Página {current} de {pages}</b><button className="mini" disabled={current>=pages} onClick={()=>setTxPage(p=>Math.min(pages,p+1))}>Próxima →</button></div></div>}</section>{kind==='gasto'&&<section className="panel card-expense-ledger"><div className="panel-head"><div><p className="eyebrow">COMPRAS NO CARTÃO</p><h2>Despesas comprometidas</h2><p className="muted">Aparecem como despesa para controle, mas não reduzem seu saldo até o vencimento da fatura.</p></div><b>{money(cardPurchases.reduce((sum,p)=>sum+Number(p.amount),0),currency)}</b></div><div className="table-wrap"><table><thead><tr><th>Compra</th><th>Cartão</th><th>Descrição</th><th>Categoria</th><th>Fatura</th><th>Valor</th></tr></thead><tbody>{cardPurchases.slice(0,30).map(p=><tr key={'cc'+p.id}><td>{localDate(p.purchased_at)}</td><td><strong>{p.card_name}</strong></td><td>{p.description}</td><td>{p.category}</td><td>{localDate(p.statement_due_date+'T12:00:00')}</td><td>{money(p.amount,p.currency)}</td></tr>)}</tbody></table></div>{!cardPurchases.length&&<p className="empty">Nenhuma compra de cartão registrada em {currency}.</p>}</section>}</>
}
function CategoriesPage({overview,currency,categories,newCat,setNewCat,onAdd}:{overview:Overview|null,currency:string,categories:any[],newCat:string,setNewCat:(s:string)=>void,onAdd:(e:FormEvent)=>void}){
  const data=overview?.categories[currency]||[];const total=data.reduce((s,c)=>s+c.amount,0);
  const[budgets,setBudgets]=useState<any[]>([]),[budgetCat,setBudgetCat]=useState(''),[budgetValue,setBudgetValue]=useState(''),[budgetMsg,setBudgetMsg]=useState('');
  const loadBudgets=()=>listCategoryBudgets().then(setBudgets).catch(e=>setBudgetMsg(e instanceof Error?e.message:'Não consegui carregar os orçamentos.'));
  useEffect(()=>{void loadBudgets()},[]);
  useEffect(()=>{if(!budgetCat&&categories.length)setBudgetCat(String(categories[0].name||''))},[categories,budgetCat]);
  async function saveBudget(e:FormEvent){e.preventDefault();const n=Number(budgetValue.replace(/\./g,'').replace(',','.'));if(!budgetCat||!Number.isFinite(n)||n<=0){setBudgetMsg('Escolha uma categoria e informe um limite válido.');return}try{await setCategoryBudget(budgetCat,currency,n,.75);setBudgetValue('');setBudgetMsg('Orçamento salvo. A Folhinha vai acompanhar os gastos da família e avisar ao chegar a 75%. 🎯');await loadBudgets()}catch(e){setBudgetMsg(e instanceof Error?e.message:'Não consegui salvar o orçamento.')}}
  async function removeBudget(id:number){if(!confirm('Remover este orçamento mensal?'))return;try{await deleteCategoryBudget(id);setBudgetMsg('Orçamento removido.');await loadBudgets()}catch(e){setBudgetMsg(e instanceof Error?e.message:'Não consegui remover o orçamento.')}}
  const visibleBudgets=budgets.filter(b=>b.currency===currency);
  return <><div className="page-title"><div><p className="eyebrow">CATEGORIAS</p><h1>Para onde seu dinheiro está indo</h1><p>Visualize os gastos e defina limites mensais para a família.</p></div></div>
  <section className="budget-section panel"><div className="panel-head"><div><p className="eyebrow">ORÇAMENTO FAMILIAR</p><h2>Quanto podemos gastar por categoria?</h2><p className="muted">Os gastos de todos os membros contam juntos. A Folhinha avisa quando a família chegar a 75% e a 100% do limite.</p></div></div>
    <form className="budget-form" onSubmit={saveBudget}><label>Categoria<select value={budgetCat} onChange={e=>setBudgetCat(e.target.value)}>{categories.map((x:any)=><option key={x.id} value={x.name}>{x.name}</option>)}</select></label><label>Limite mensal ({currency})<input inputMode="decimal" placeholder="Ex.: 40000" value={budgetValue} onChange={e=>setBudgetValue(e.target.value)} required/></label><button>Salvar orçamento</button></form>
    <div className="budget-grid">{visibleBudgets.map(b=>{const pct=Math.max(0,Number(b.percent_used||0));return <article className="budget-card" key={b.id}><div><strong>{b.category}</strong><span>{pct.toFixed(0)}%</span></div><div className="budget-track"><i style={{width:Math.min(100,pct)+'%'}}/></div><p><b>{money(b.spent,b.currency)}</b> de {money(b.monthly_limit,b.currency)}</p><small>{pct>=100?'🚨 Limite atingido':pct>=75?'⚠️ Atenção ao limite':'✅ Dentro do planejado'} • restam {money(b.remaining,b.currency)}</small><button type="button" onClick={()=>removeBudget(b.id)}>Remover</button></article>})}{!visibleBudgets.length&&<p className="muted">Nenhum orçamento em {currency} ainda. Você também pode criar pelo chat, por exemplo: “quero gastar no máximo 40 mil ienes com mercado por mês”.</p>}</div>
    {budgetMsg&&<p className="form-message">{budgetMsg}</p>}
  </section>
  <section className="grid categories-grid"><article className="panel"><p className="eyebrow">DISTRIBUIÇÃO</p><h2>Despesas por categoria</h2><div className="pie-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data} dataKey="amount" nameKey="name" innerRadius="46%" outerRadius="76%" paddingAngle={2}>{data.map((_,i)=><Cell key={i} fill={PIE_COLORS[i%PIE_COLORS.length]}/>)}</Pie><Tooltip formatter={(v)=>money(Number(v),currency)}/><Legend/></PieChart></ResponsiveContainer></div><div className="pie-total"><span>Total analisado</span><b>{money(total,currency)}</b></div></article><article className="panel"><p className="eyebrow">GERENCIAR</p><h2>Suas categorias</h2><div className="stack category-list">{categories.map((c:any)=><div className="category" key={c.id}><span>{c.name}</span><small>{c.is_default?'padrão':'personalizada'}</small></div>)}</div><form className="inline-form" onSubmit={onAdd}><input placeholder="Nova categoria" value={newCat} onChange={e=>setNewCat(e.target.value)}/><button>Adicionar</button></form></article></section></>
}

function CommitmentsPage({items,recurring}:{items:any[],recurring:any[]}){
  const now=new Date();const[view,setView]=useState(new Date(now.getFullYear(),now.getMonth(),1));const[selectedDay,setSelectedDay]=useState<number|null>(null);
  const year=view.getFullYear(),month=view.getMonth(),days=new Date(year,month+1,0).getDate(),first=new Date(year,month,1).getDay();
  const monthName=view.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
  const commitmentsByDay=new Map<number,any[]>();for(const c of items){const d=new Date(c.starts_at);if(d.getFullYear()===year&&d.getMonth()===month){const a=commitmentsByDay.get(d.getDate())||[];a.push(c);commitmentsByDay.set(d.getDate(),a)}}
  const paymentsByDay=new Map<number,any[]>();for(const r of recurring){if(!r.active||!r.day_of_month)continue;const day=Math.min(Number(r.day_of_month),days),a=paymentsByDay.get(day)||[];a.push(r);paymentsByDay.set(day,a)}
  const cells:Array<number|null>=[...Array(first).fill(null),...Array.from({length:days},(_,i)=>i+1)];while(cells.length%7)cells.push(null);
  function move(delta:number){setView(new Date(year,month+delta,1));setSelectedDay(null)}
  return <><div className="page-title"><div><p className="eyebrow">COMPROMISSOS</p><h1>Próximos compromissos</h1><p>A Folhinha mostra apenas o título limpo, data e horário.</p></div></div><section className="panel"><div className="commitment-grid">{items.map(c=><article className="commitment-card" key={c.id}><div className="date-badge large">{new Date(c.starts_at).getDate()}</div><div><h3>{c.title}</h3><p>{new Date(c.starts_at).toLocaleString('pt-BR',{dateStyle:'full',timeStyle:'short'})}</p></div></article>)}</div>{!items.length&&<p className="empty">Nenhum compromisso futuro registrado.</p>}</section><section className="panel calendar-panel"><div className="calendar-head"><div><p className="eyebrow">VISÃO MENSAL</p><h2>{monthName}</h2></div><div className="calendar-nav"><button onClick={()=>move(-1)} aria-label="Mês anterior">‹</button><button onClick={()=>setView(new Date(now.getFullYear(),now.getMonth(),1))}>Hoje</button><button onClick={()=>move(1)} aria-label="Próximo mês">›</button></div></div><div className="calendar-legend"><span><i className="dot commitment-dot"/>Compromisso</span><span><i className="dot payment-dot"/>Pagamento</span></div><div className="calendar-weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=><span key={x}>{x}</span>)}</div><div className="calendar-grid">{cells.map((day,i)=>{if(!day)return <div className="calendar-cell empty-day" key={`e${i}`}/>;const cs=commitmentsByDay.get(day)||[],ps=paymentsByDay.get(day)||[],hasPay=ps.length>0,isToday=day===now.getDate()&&month===now.getMonth()&&year===now.getFullYear();return <button type="button" className={`calendar-cell ${isToday?'today':''} ${selectedDay===day?'selected':''}`} key={day} onClick={()=>setSelectedDay(day)}><span className="calendar-day-number">{day}</span><div className="calendar-dots">{!!cs.length&&<i className="dot commitment-dot" title={`${cs.length} compromisso(s)`}/>} {hasPay&&<i className="dot payment-dot" title="Pagamento previsto"/>}</div>{cs.length>0&&<small>{cs[0].title}{cs.length>1?` +${cs.length-1}`:''}</small>}</button>})}</div>{selectedDay&&<div className="day-details"><div className="day-details-head"><div><p className="eyebrow">AGENDA DO DIA</p><h3>{new Date(year,month,selectedDay).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</h3></div><button className="icon-btn" onClick={()=>setSelectedDay(null)} aria-label="Fechar detalhes">×</button></div>{(commitmentsByDay.get(selectedDay)||[]).map(c=><article className="day-detail-row" key={`c${c.id}`}><i className="dot commitment-dot"/><div><strong>{c.title}</strong><small>Compromisso • {new Date(c.starts_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div></article>)}{(paymentsByDay.get(selectedDay)||[]).map(r=><article className="day-detail-row" key={`p${r.id}`}><i className="dot payment-dot"/><div><strong>{r.description}</strong><small>Pagamento previsto{r.amount!=null?` • ${money(r.amount,r.currency)}`:''}{r.category?` • ${r.category}`:''}</small></div></article>)}{!(commitmentsByDay.get(selectedDay)||[]).length&&!(paymentsByDay.get(selectedDay)||[]).length&&<p className="empty day-empty">Nenhum compromisso ou pagamento previsto para este dia.</p>}</div>}</section></>
}

function PlansPage({account,plans,onReload}:{account:AccountInfo|null,plans:PlanInfo[],onReload:()=>void}){
  const[token,setToken]=useState('');const[msg,setMsg]=useState('');const[busy,setBusy]=useState(false);const[cfg,setCfg]=useState<any>(null);const[offers,setOffers]=useState<any[]>([]);
  const hasAccess=accountHasAccess(account);useEffect(()=>{Promise.all([loadCommercialSettings(),loadCommercialOffers()]).then(([c,o])=>{setCfg(c);setOffers(o)}).catch(()=>{})},[]);
  const launch=cfg?.commercial_launch_enabled===true;
  function price(plan:any){if(plan.code==='beta')return 'Grátis durante o beta';if(plan.amount_minor==null)return 'Preço definido no lançamento';return new Intl.NumberFormat('pt-BR',{style:'currency',currency:plan.currency}).format(plan.amount_minor/100)+` / ${plan.interval==='year'?'ano':'mês'}`}
  async function redeem(e:FormEvent){e.preventDefault();if(!token.trim())return;setBusy(true);setMsg('');try{await redeemBetaInvite(token);setToken('');localStorage.removeItem('planeja_beta_invite');setMsg('Convite ativado. Seu acesso beta está liberado. 🍃');await onReload()}catch(err){setMsg(err instanceof Error?err.message:'Convite inválido ou expirado.')}finally{setBusy(false)}}
  async function checkout(offer:string){setBusy(true);setMsg('');try{await startSubscriptionCheckout(offer)}catch(err){setMsg(err instanceof Error?err.message:'Checkout ainda não está disponível.');setBusy(false)}}
  async function trial(){setBusy(true);setMsg('');try{const r:any=await startCommercialTrial();setMsg(`Seu teste grátis está ativo até ${new Date(r.ends_at).toLocaleDateString('pt-BR')}. 🍃`);await onReload()}catch(err){setMsg(err instanceof Error?err.message:'Não consegui ativar o teste grátis.')}finally{setBusy(false)}}
  async function portal(){setBusy(true);setMsg('');try{await openBillingPortal()}catch(err){setMsg(err instanceof Error?err.message:'Portal de cobrança ainda não está disponível.');setBusy(false)}}
  const trialAvailable=launch&&cfg?.self_serve_trial_enabled&&!hasAccess&&!account?.commercial_trial_consumed_at;
  const shown:any[]=launch?offers:plans;
  return <><div className="page-title"><div><p className="eyebrow">PLANOS E ACESSO</p><h1>{hasAccess?'Seu plano':launch?'Experimente o Planeja+':'Ative seu acesso'}</h1><p>{launch?'Comece sem cartão no teste grátis e assine somente se fizer sentido para você.':'Durante o beta, o Planeja+ funciona por convite. A cobrança via Stripe permanece desativada até o lançamento oficial.'}</p></div></div>{trialAvailable&&<section className="panel trial-offer"><p className="eyebrow">TESTE GRÁTIS</p><h2>{cfg.trial_days} dias para usar de verdade</h2><p>Sem cobrança e sem cartão para começar. Organize seus gastos, compromissos e metas com a Folhinha antes de decidir.</p><button className="upgrade" disabled={busy} onClick={trial}>{busy?'Ativando…':`Começar ${cfg.trial_days} dias grátis`}</button></section>}<section className="plans-grid">{shown.map((plan:any)=>{const current=plan.plan_code?plan.plan_code===account?.subscription_plan:plan.code===account?.subscription_plan||(plan.code==='beta'&&!!account?.beta_access);return <article className={`panel plan-option ${current?'current':''}`} key={plan.code}><div className="plan-option-head"><div><p className="eyebrow">{current?'PLANO ATUAL':plan.code==='beta'?'BETA FECHADO':launch?'OFERTA':'LANÇAMENTO'}</p><h2>{plan.name}</h2></div>{current&&<span className="plan-badge">Ativo</span>}</div><strong className="plan-price">{price(plan)}</strong><p className="muted">{plan.description}</p><ul>{(plan.features||[]).map((f:string)=><li key={f}>✓ {f}</li>)}</ul>{!launch&&plan.code==='beta'?<>{account?.beta_access?<button className="upgrade" disabled>Acesso beta liberado</button>:<form className="invite-form" onSubmit={redeem}><input placeholder="Cole seu código de convite" value={token} onChange={e=>setToken(e.target.value)}/><button disabled={busy}>Ativar convite</button></form>}</>:launch?<button className="upgrade" disabled={busy||current} onClick={()=>checkout(plan.code)}>{current?'Plano atual':'Assinar com Stripe'}</button>:<button className="upgrade" disabled>Assinaturas abrem no lançamento</button>}</article>})}</section><section className="panel billing-status"><div><p className="eyebrow">COBRANÇA</p><h2>{launch?'Cobrança protegida pelo Stripe':'Stripe preparado, cobranças desativadas no beta'}</h2><p className="muted">{launch?'Você gerencia cartão, faturas e cancelamento no portal seguro do Stripe.':'Quando a versão oficial for ativada, o checkout criará a assinatura e o acesso será atualizado automaticamente pelos webhooks do Stripe.'}</p></div><div className="billing-summary"><span>Status da conta</span><b>{account?.beta_access?'Beta autorizado':account?.subscription_status||'Sem acesso'}</b>{account?.commercial_trial_ends_at&&new Date(account.commercial_trial_ends_at)>new Date()&&<small>Teste grátis até {new Date(account.commercial_trial_ends_at).toLocaleDateString('pt-BR')}</small>}{account?.current_period_ends_at&&<small>Período atual até {new Date(account.current_period_ends_at).toLocaleDateString('pt-BR')}</small>}{account?.billing_customer_id&&<button className="ghost" disabled={busy} onClick={portal}>Gerenciar cobrança</button>}</div></section>{msg&&<div className="toast-inline">{msg}</div>}</>}

function HouseholdCard(){
 const[members,setMembers]=useState<any[]>([]),[name,setName]=useState(''),[email,setEmail]=useState(''),[link,setLink]=useState(''),[msg,setMsg]=useState('');
 const[selected,setSelected]=useState<any>(null),[phone,setPhone]=useState(''),[busy,setBusy]=useState(false),[waLink,setWaLink]=useState(''),[expires,setExpires]=useState(''),[loadError,setLoadError]=useState('');
 async function refresh(){try{setMembers(await listHouseholdChatMembers());setLoadError('')}catch{setLoadError('Não consegui carregar os membros. Tente atualizar.')}}
 useEffect(()=>{void refresh()},[]);
 async function invite(e:FormEvent){e.preventDefault();setMsg('');try{const r=await createHouseholdInvite(name,email);const bot='financeassistenbot';const url=`https://t.me/${bot}?start=family_${r.token}`;setLink(url);setMsg(`Convite criado. Ele expira em ${r.expires_in_days} dias. 🍃`)}catch(e){const anyErr=e as any;setMsg(anyErr?.message||'Não consegui criar o convite. Tente novamente.')}}
 async function whatsapp(e:FormEvent){e.preventDefault();if(!selected)return;setBusy(true);setMsg('');setWaLink('');try{const r=await connectHouseholdWhatsApp(selected.user_id,phone);setExpires(r.expires_at||'');if(r.sent){setMsg(`📲 A Folhinha enviou a primeira mensagem para ${selected.first_name||'esse membro'} no WhatsApp. A pessoa só precisa abrir a conversa e responder. 🍃`);await refresh()}else{setWaLink(r.url||'');setMsg(r.requires_member_opt_in?'Para proteger a privacidade do membro, ele precisa autorizar o WhatsApp antes de a Folhinha iniciar a conversa. Enquanto isso, use o link individual abaixo.':'')}}catch(e){setMsg(e instanceof Error?e.message:'Não consegui preparar a conexão.')}finally{setBusy(false)}}
 async function copy(value:string){try{await navigator.clipboard.writeText(value);setMsg('Link copiado. Envie somente para a pessoa indicada.')}catch{setMsg('Selecione o link e copie manualmente.')}}
 const isOwner=members.some(m=>m.can_connect_whatsapp);
 return <article className="panel"><p className="eyebrow">FAMÍLIA</p><h2>Membros da conta</h2><p className="muted">Cada pessoa usa a Folhinha pelo próprio WhatsApp ou Telegram. Os lançamentos continuam na mesma família, com o histórico de cada membro.</p><button className="ghost" onClick={refresh}>Atualizar conexões</button>{loadError&&<p role="alert">{loadError}</p>}<div className="stack">{members.map(m=><div className="row" key={m.user_id}><div><strong>{m.first_name||m.email||'Membro'}</strong><small>{m.role==='owner'?'Titular':'Membro'} • {m.telegram_connected?'Telegram conectado':'Sem Telegram'} • {m.whatsapp_connected?'WhatsApp conectado':'WhatsApp não conectado'}</small></div>{m.can_connect_whatsapp&&!m.whatsapp_connected&&<button className="ghost" disabled={busy} onClick={()=>{setSelected(m);setPhone('');setWaLink('');setMsg('')}}>Conectar WhatsApp</button>}</div>)}</div>
 {selected&&<form className="settings-form" onSubmit={whatsapp}><h3>WhatsApp de {selected.first_name||'membro'}</h3><p className="muted">Informe o número dessa pessoa, incluindo o código do país. Se esse membro já autorizou mensagens do Planeja+ no WhatsApp, a Folhinha inicia a conversa automaticamente. Caso ainda não tenha autorizado, o sistema gera um link individual de conexão. Não precisa criar outra conta nem refazer o cadastro.</p><label>Número do membro com código do país<input type="tel" inputMode="tel" placeholder="+81… ou +55…" autoComplete="off" value={phone} disabled={busy||!!waLink} onChange={e=>setPhone(e.target.value)} required/></label><button disabled={busy}>{busy?'Preparando…':waLink?'Gerar novo link':'Conectar WhatsApp'}</button><button className="ghost" type="button" disabled={busy} onClick={()=>{setSelected(null);setWaLink('')}}>Fechar</button>{waLink&&<><label className="invite-link">Link de {selected.first_name||'membro'}<input readOnly value={waLink} onFocus={e=>e.currentTarget.select()}/></label><small>Válido até {new Date(expires).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}. Uso único, somente pelo número informado.</small><button className="ghost" type="button" onClick={()=>copy(waLink)}>Copiar link para o membro</button></>}</form>}
 {isOwner&&<form className="settings-form" onSubmit={invite}><h3>Adicionar novo membro</h3><label>Nome do novo membro<input value={name} onChange={e=>setName(e.target.value)} required/></label><label>E-mail (opcional)<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><button>Gerar convite para Telegram</button><small>Após aceitar o convite, o membro também poderá conectar o WhatsApp acima.</small></form>}{link&&<><label className="invite-link">Link do convite<input readOnly value={link} onFocus={e=>e.currentTarget.select()}/></label><button className="ghost" onClick={()=>copy(link)}>Copiar link</button></>}{msg&&<p className="form-message" role="status">{msg}</p>}</article>
}

function AccountPage({account,onReload}:{account:AccountInfo|null,onReload:()=>void}){
  const[name,setName]=useState(account?.first_name||'');
  const[cur,setCur]=useState(account?.default_currency||'JPY');
  const[tz,setTz]=useState(account?.timezone||'Asia/Tokyo');
  const[msg,setMsg]=useState('');const[chatBusy,setChatBusy]=useState(false);const[privacyBusy,setPrivacyBusy]=useState(false);const[deleteOpen,setDeleteOpen]=useState(false);const[deleteText,setDeleteText]=useState('');const[pwaPrompt,setPwaPrompt]=useState<any>(null);const[pwaInstalled,setPwaInstalled]=useState(false);const[pwaIos,setPwaIos]=useState(false);
  async function save(e:FormEvent){e.preventDefault();setMsg('');try{await updateAccount({first_name:name,default_currency:cur,timezone:tz});setMsg('Configurações salvas. 🍃');onReload()}catch(e){setMsg(e instanceof Error?e.message:'Erro ao salvar')}}
  useEffect(()=>{const standalone=window.matchMedia('(display-mode: standalone)').matches||(navigator as any).standalone===true;setPwaInstalled(standalone);setPwaIos(/iphone|ipad|ipod/i.test(navigator.userAgent));const before=(event:any)=>{event.preventDefault();setPwaPrompt(event)};const installed=()=>{setPwaInstalled(true);setPwaPrompt(null);setMsg('Planeja+ instalado neste dispositivo. 📱🍃')};window.addEventListener('beforeinstallprompt',before as EventListener);window.addEventListener('appinstalled',installed);return()=>{window.removeEventListener('beforeinstallprompt',before as EventListener);window.removeEventListener('appinstalled',installed)}},[]);
  async function installPwa(){if(pwaInstalled){setMsg('O Planeja+ já está instalado neste dispositivo. 📱🍃');return}if(pwaPrompt){await pwaPrompt.prompt();const choice=await pwaPrompt.userChoice;if(choice?.outcome==='accepted'){setPwaInstalled(true);setPwaPrompt(null);setMsg('Instalação iniciada. Depois, abra o Planeja+ pelo ícone da tela inicial. 📱🍃')}return}if(pwaIos){setMsg('No iPhone/iPad: abra este site no Safari → toque em Compartilhar ⬆️ → “Adicionar à Tela de Início” → Adicionar. Depois o Planeja+ abre como aplicativo. 📱')}else setMsg('Seu navegador não mostrou o botão automático agora. Abra o menu do navegador e escolha “Instalar app” ou “Adicionar à tela inicial”. 📱')}
  async function connectChannel(channel:'whatsapp'|'telegram'){setChatBusy(true);setMsg('');try{const r=await connectChatChannel(channel);if(channel==='whatsapp'&&r?.sent)setMsg('📲 A Folhinha te mandou uma mensagem no WhatsApp. Abra a conversa e responda para concluir. 🍃');else if(channel==='whatsapp'&&r?.connected)setMsg('✅ Seu WhatsApp já está conectado. 🍃')}catch(e){setMsg(e instanceof Error?e.message:'Não consegui abrir a conexão da Folhinha.')}finally{setChatBusy(false)}}
  async function downloadData(format:'json'|'csv'){setPrivacyBusy(true);setMsg('');try{const data=await exportMyData(),day=new Date().toISOString().slice(0,10);if(format==='csv')downloadPortableFile(`planeja-mais-movimentacoes-${day}.csv`,familyTransactionsCsv(data),'text/csv;charset=utf-8');else downloadPortableFile(`planeja-mais-backup-completo-${day}.json`,JSON.stringify(data,null,2),'application/json;charset=utf-8');setMsg(format==='csv'?'Movimentações da família exportadas em CSV. Dá para abrir no Excel ou Google Planilhas. 🍃':'Backup completo preparado. Ele inclui seus dados pessoais e os dados financeiros compartilhados da família, sem senhas ou segredos de integrações. 🔐🍃')}catch(e){setMsg(e instanceof Error?e.message:'Não consegui preparar seus dados.')}finally{setPrivacyBusy(false)}}
  async function removeAccount(){if(deleteText!=='EXCLUIR'){setMsg('Digite EXCLUIR exatamente para confirmar.');return}if(!confirm('Excluir sua conta Planeja+ definitivamente? Seus dados pessoais serão removidos e uma assinatura Stripe ativa será cancelada. Essa ação não pode ser desfeita.'))return;setPrivacyBusy(true);setMsg('');try{await deleteMyAccount(deleteText);try{await supabase.auth.signOut({scope:'global'})}catch{}window.location.assign('/?deleted=1')}catch(e){setMsg(e instanceof Error?e.message:'Não consegui excluir sua conta. Entre em contato com o suporte se o problema continuar.');setPrivacyBusy(false)}}
  const theme=localStorage.getItem('planeja_theme')||'system',density=localStorage.getItem('planeja_density')||'comfortable';
  function setTheme(v:string){localStorage.setItem('planeja_theme',v);applyLayout();setMsg('Layout atualizado. 🍃')}
  function setDensity(v:string){localStorage.setItem('planeja_density',v);applyLayout();setMsg('Layout atualizado. 🍃')}
  return <><div className="page-title"><div><p className="eyebrow">CONTA E CONFIGURAÇÕES</p><h1>Sua conta</h1><p>Preferências, privacidade, layout e plano.</p></div></div><section className="settings-grid"><article className="panel"><p className="eyebrow">PERFIL</p><h2>Dados da conta</h2><form className="settings-form" onSubmit={save}><label>E-mail<input value={account?.email||''} disabled/></label><label>Nome<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Moeda padrão<select value={cur} onChange={e=>setCur(e.target.value)}>{ISO_CURRENCY_CODES.map(c=><option key={c}>{c}</option>)}</select></label><label>Fuso horário<select value={tz} onChange={e=>setTz(e.target.value)}>{IANA_TIME_ZONES.map(z=><option key={z}>{z}</option>)}</select></label><button>Salvar configurações</button></form></article><HouseholdCard/><article className="panel"><p className="eyebrow">CANAL DA FOLHINHA</p><h2>WhatsApp ou Telegram</h2><p className="muted">{account?.preferred_chat==='whatsapp'?'Seu canal preferido está no WhatsApp.':'Conecte o WhatsApp para usar a Folhinha no canal mais simples do dia a dia.'}</p><div className="chat-buttons"><button className="preferred" disabled={chatBusy} onClick={()=>connectChannel('whatsapp')}><span>WA</span><div><b>{account?.preferred_chat==='whatsapp'?'Reconectar WhatsApp':'Conectar WhatsApp'}</b><small>Conexão oficial e segura</small></div></button><button disabled={chatBusy} onClick={()=>connectChannel('telegram')}><span>TG</span><div><b>Conectar Telegram</b><small>Continua disponível como alternativa</small></div></button></div><small className="muted">Número cadastrado: {account?.phone_e164||'não informado'}</small></article><article className="panel"><p className="eyebrow">LEMBRETES</p><h2>Agenda da Folhinha</h2><p className="muted">Seus compromissos ficam no Planeja+. Nos dias em que houver algo marcado, a Folhinha envia um resumo pela manhã no seu canal de conversa.</p><div className="integration-row"><div className="integration-icon">🍃</div><div><strong>Resumo do dia</strong><small>Compromissos, vencimentos e prazos importantes</small></div></div></article><article className="panel"><p className="eyebrow">LAYOUT</p><h2>Aparência do painel</h2><div className="settings-form"><label>Tema<select defaultValue={theme} onChange={e=>setTheme(e.target.value)}><option value="system">Sistema</option><option value="light">Claro</option><option value="dark">Escuro</option></select></label><label>Densidade<select defaultValue={density} onChange={e=>setDensity(e.target.value)}><option value="comfortable">Confortável</option><option value="compact">Compacto</option></select></label></div></article><article className="panel pwa-install-card"><p className="eyebrow">APLICATIVO</p><div className="pwa-install-head"><div><h2>Planeja+ na tela inicial 📱</h2><p className="muted">Instale sem App Store. Ele ganha ícone próprio e abre em uma janela limpa, como aplicativo.</p></div>{pwaInstalled&&<span className="pill receita">Instalado</span>}</div>{pwaInstalled?<div className="pwa-installed"><span>✅</span><p>Este dispositivo já está usando o Planeja+ como aplicativo.</p></div>:<><button className="pwa-install-button" onClick={installPwa}>{pwaPrompt?'Instalar Planeja+ agora':pwaIos?'Como instalar no iPhone':'Instalar no dispositivo'}</button><small className="muted">{pwaIos?'No iPhone, a instalação é concluída pelo menu Compartilhar do Safari.':'No Android, Chrome/Edge e computadores compatíveis, a instalação pode aparecer diretamente pelo navegador.'}</small></>}</article><article className="panel plan-card"><p className="eyebrow">PLANO</p><h2>{account?.subscription_plan||'beta'}</h2><span className={`pill ${accountHasAccess(account)?'receita':'gasto'}`}>{accountHasAccess(account)?'Acesso liberado':'Acesso suspenso'}</span><p>{account?.billing_enabled?`Status: ${account.subscription_status}`:'Beta gratuito — nenhuma cobrança ativa.'}</p><button className="upgrade" onClick={()=>setMsg('Os planos pagos ainda não foram ativados. Quando definirmos preço e trial, este botão abrirá o checkout real.')}>Ver opções de upgrade</button></article><article className="panel privacy-card"><p className="eyebrow">PRIVACIDADE E DADOS</p><h2>Seus dados são seus</h2><p className="muted">Leve seus dados com você quando quiser. O backup completo inclui seus dados pessoais e as informações financeiras compartilhadas da família. Dados privados de contato dos outros membros, senhas e segredos de integrações nunca entram no arquivo.</p><div className="privacy-export-actions"><button className="ghost" disabled={privacyBusy} onClick={()=>downloadData('json')}>{privacyBusy?'Preparando…':'📦 Backup completo (.json)'}</button><button className="ghost" disabled={privacyBusy} onClick={()=>downloadData('csv')}>{privacyBusy?'Preparando…':'📊 Movimentações (.csv)'}</button></div><small className="muted privacy-export-note">O CSV abre no Excel e Google Planilhas. O JSON preserva a estrutura completa para backup ou migração futura.</small><hr/><h3>Excluir conta</h3><p className="muted">A exclusão cancela uma assinatura ativa, remove seus dados pessoais e encerra seu acesso. Se você for titular de uma família com outros membros, a titularidade passa para outro membro.</p>{!deleteOpen?<button className="danger-button" onClick={()=>setDeleteOpen(true)}>Excluir minha conta</button>:<div className="delete-confirm"><label>Para confirmar, digite <b>EXCLUIR</b><input value={deleteText} onChange={e=>setDeleteText(e.target.value)} autoComplete="off"/></label><div className="delete-actions"><button className="ghost" onClick={()=>{setDeleteOpen(false);setDeleteText('')}}>Cancelar</button><button className="danger-button" disabled={privacyBusy||deleteText!=='EXCLUIR'} onClick={removeAccount}>{privacyBusy?'Excluindo…':'Excluir definitivamente'}</button></div></div>}</article></section>{msg&&<div className="toast-inline">{msg}</div>}</>}

